<script>
document.addEventListener('DOMContentLoaded',()=>{
 'use strict';
 const $=id=>document.getElementById(id);
 const rawServer=@json($courierRegistrations);
 const backendCenterId=@json($assignedSortingCenterId);
 // Demo fallback only when no center has been assigned yet. Never use for real cross-center authorization.
 const assignedCenterId=(backendCenterId===null||String(backendCenterId).trim()==='')?'SC-LAGUNA-DEMO':backendCenterId;
 const matchesAssignedCenter=r=>assignedCenterId!==null&&assignedCenterId!==undefined&&String(assignedCenterId).trim()!==''&&String(r.sorting_center_id??r.selected_sorting_center_id??r.applied_sorting_center_id??'')===String(assignedCenterId);
 const storeKey='shopease-sorting-center-courier-registrations-preview-v1';
 // Only applications explicitly assigned to this logged-in center are shown.
 // Demo applicants are fictional and supplied only when the controller does not supply registration data.
 // Without a trusted center ID, show no registrations instead of another center's data.
 let records,selected=null,page=1,archiveStatus='approved';
 const serverRecords=Array.isArray(rawServer)?rawServer:(Array.isArray(rawServer?.data)?rawServer.data:null);
 const demoApplicants=[
  {id:'demo-sc-courier-001',first_name:'Mark',middle_name:'Angelo',last_name:'Reyes',sex:'Male',birthday:'1998-03-15',email:'mark.reyes@example.com',phone:'09170000001',region:'CALABARZON (Region IV-A)',province:'Laguna',city:'Santa Cruz',barangay:'Poblacion I',street:'Rizal Street',house_no:'123',postal_code:'4009',vehicle:'Truck',plate_number:'ABC 1234',status:'pending',created_at:'2026-10-26T08:30:00+08:00'},
  {id:'demo-sc-courier-002',first_name:'Joshua',middle_name:'Miguel',last_name:'Santos',sex:'Male',birthday:'1996-07-24',email:'joshua.santos@example.com',phone:'09170000002',region:'CALABARZON (Region IV-A)',province:'Laguna',city:'Pila',barangay:'Santa Clara Norte',street:'Mabini Street',house_no:'45',postal_code:'4010',vehicle:'Truck',plate_number:'DEF 5678',status:'pending',created_at:'2026-10-27T09:45:00+08:00'},
  {id:'demo-sc-courier-003',first_name:'Adrian',middle_name:'Paul',last_name:'Mendoza',sex:'Male',birthday:'1999-01-08',email:'adrian.mendoza@example.com',phone:'09170000003',region:'CALABARZON (Region IV-A)',province:'Laguna',city:'Calamba',barangay:'Real',street:'National Highway',house_no:'88',postal_code:'4027',vehicle:'Truck',plate_number:'GHI 9012',status:'approved',created_at:'2026-10-23T13:15:00+08:00',reviewed_at:'2026-10-25T10:00:00+08:00'},
  {id:'demo-sc-courier-004',first_name:'Carlo',middle_name:'Vincent',last_name:'Cruz',sex:'Male',birthday:'1997-11-19',email:'carlo.cruz@example.com',phone:'09170000004',region:'CALABARZON (Region IV-A)',province:'Laguna',city:'San Pablo',barangay:'San Francisco',street:'Bonifacio Street',house_no:'17',postal_code:'4000',vehicle:'Truck',plate_number:'JKL 3456',status:'rejected',created_at:'2026-10-21T14:00:00+08:00',reviewed_at:'2026-10-22T16:30:00+08:00',rejection_reason:'Unclear or unreadable uploaded documents'}
 ].map(r=>({...r,sorting_center_id:assignedCenterId}));
 const useDemo=serverRecords===null;
 const rawRecords=useDemo?demoApplicants:serverRecords;
 records=rawRecords.filter(matchesAssignedCenter).map(r=>({...r,id:String(r.id),status:r.status||'pending'}));
 // For frontend preview, decisions are scoped to the center and never fabricate applications.
 try {const saved=JSON.parse(localStorage.getItem(storeKey+':'+String(assignedCenterId))||'[]');if(Array.isArray(saved)){const byId=new Map(saved.map(r=>[String(r.id),r]));records=records.map(r=>{const prior=byId.get(r.id);return prior&&matchesAssignedCenter(prior)?{...r,status:prior.status,reviewed_at:prior.reviewed_at,rejection_reason:prior.rejection_reason}:r})}}catch{}
 const persist=()=>{try{localStorage.setItem(storeKey+':'+String(assignedCenterId),JSON.stringify(records))}catch{}};
 const esc=x=>String(x??'—').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 const val=(r,...keys)=>{for(const k of keys){if(r[k]!==undefined&&r[k]!==null&&r[k]!=='')return r[k]}return '—'};
 const name=r=>[r.first_name,r.middle_name,r.last_name].filter(Boolean).join(' ')||(val(r,'full_name')!=='—'?String(r.full_name):'Unknown Applicant');
 const initials=r=>name(r).split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
 const fdate=s=>{if(!s)return '—';const d=new Date(s);return Number.isNaN(+d)?String(s):new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',year:'numeric',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d)};
 const status=r=>String(r.status||'pending').toLowerCase();
 const field=(label,value)=>`<div class="cr-field"><label>${esc(label)}</label><strong>${esc(value)}</strong></div>`;
 const img=(r,key,label)=>{const url=r[key]||r[key+'_url']||r.documents?.[key]||null;const safe=(typeof url==='string'&&/^(https?:\/\/|\/)/i.test(url))?url:null;return `<div class="cr-photo">${safe?`<a href="${esc(safe)}" target="_blank" rel="noopener"><img alt="${esc(label)}" src="${esc(safe)}"></a>`:`<div class="empty">No ${esc(label)} uploaded<br><small>Awaiting backend document URL</small></div>`}<strong>${esc(label)}</strong><small>${safe?'Click image to inspect':'No demo document is fabricated'}</small></div>`};
 const modal=id=>$(id).hidden=false;const closeAll=()=>{document.querySelectorAll('.cr-modal').forEach(m=>m.hidden=true);document.body.style.overflow=''};
 function flash(msg,bad=false,title=''){const e=$('crFlash');e.className='cr-flash'+(bad?' error':'');$('crFlashTitle').textContent=title||(bad?'Action Failed':'Action Successful');$('crFlashMessage').textContent=msg;$('crFlashIcon').innerHTML=bad?'<svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg>':'<svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg>';e.hidden=false;clearTimeout(flash.timer);flash.timer=setTimeout(()=>e.hidden=true,3800)}
 $('crFlashClose').addEventListener('click',()=>{clearTimeout(flash.timer);$('crFlash').hidden=true});
 function update(){for(const k of ['pending','approved','rejected'])$('cr'+k[0].toUpperCase()+k.slice(1)).textContent=records.filter(r=>status(r)===k).length;$('crTotal').textContent=records.length;let filtered=records.filter(r=>{const q=$('crSearch').value.trim().toLowerCase(),s=$('crStatus').value,date=$('crDate').value;return(s==='all'||status(r)===s)&&(!date||String(r.created_at||'').slice(0,10)===date)&&(!q||[name(r),r.email,r.phone,r.plate_number].join(' ').toLowerCase().includes(q))});const n=filtered.length,size=10,max=Math.max(1,Math.ceil(n/size));page=Math.min(page,max);const shown=filtered.slice((page-1)*size,page*size);$('crRows').innerHTML=shown.map(r=>`<tr class="cr-row" tabindex="0" role="button" data-id="${esc(r.id)}"><td><div class="cr-person"><span class="cr-avatar">${esc(initials(r))}</span><strong>${esc(name(r))}</strong></div></td><td>Courier (Truck Driver)</td><td style="color:#938b88">${esc(r.email)}</td><td>${esc(r.phone)}</td><td>${esc(fdate(r.created_at))}</td><td><span class="cr-badge ${esc(status(r))}">${esc(status(r).toUpperCase())}</span></td></tr>`).join('')||'<tr><td colspan="6" class="cr-empty">No courier applications for this sorting center yet.</td></tr>';$('crShowing').textContent=`${n} registration${n===1?'':'s'}`;$('crPageText').textContent=n?`Showing ${(page-1)*size+1}–${Math.min(page*size,n)} of ${n}`:'0 results';$('crPageNumber').textContent=String(page);$('crPrev').disabled=page===1;$('crNext').disabled=page===max;}
 function details(id){selected=records.find(r=>String(r.id)===String(id));if(!selected)return;let r=selected;$('crDetailsTitle').textContent='Courier Details';const address=[r.street,r.house_no,r.barangay,r.city||r.municipality,r.province,r.region,r.postal_code].filter(x=>x&&x!=='—').join(', ');let birth=String(val(r,'birthday','birth_date'));const age=/^\d{4}-/.test(birth)?Math.floor((Date.now()-new Date(birth).getTime())/31557600000):val(r,'age');$('crDetailsBody').innerHTML=`<div class="cr-profile"><span class="cr-avatar">${esc(initials(r))}</span><div><strong>${esc(name(r))}</strong><small>Courier / Truck Driver · <span class="cr-badge ${esc(status(r))}">${esc(status(r))}</span></small></div></div><h3 class="cr-section">Personal Information</h3><div class="cr-grid">${field('Last Name',val(r,'last_name'))}${field('First Name',val(r,'first_name'))}${field('Middle Name',val(r,'middle_name'))}${field('Sex',val(r,'sex'))}${field('Birthday',birth)}${field('Age',age)}${field('Email Address',val(r,'email'))}${field('Contact Number',val(r,'phone','contact_no'))}${field('Date Registered',fdate(r.created_at))}</div><h3 class="cr-section">Address Information</h3><div class="cr-grid">${field('Region',val(r,'region'))}${field('Province / City',val(r,'province'))}${field('Municipality / City',val(r,'city','municipality'))}${field('Barangay',val(r,'barangay'))}${field('Street',val(r,'street'))}${field('House Number',val(r,'house_no','house_number'))}${field('Zip Code',val(r,'postal_code','zip_code'))}</div><h3 class="cr-section">Vehicle Information</h3><div class="cr-grid">${field('Vehicle Type',val(r,'vehicle','vehicle_type'))}${field('Plate Number',val(r,'plate_number'))}</div><h3 class="cr-section">Uploaded Documents</h3><div class="cr-photos">${img(r,'or_cr','OR / CR')}${img(r,'drivers_license','Driver’s License')}</div><p class="cr-help" style="margin-top:12px">Uploaded document photos will display when the backend supplies accessible file URLs. Passwords are intentionally not shown.</p>${status(r)==='rejected'?`<h3 class="cr-section">Rejection Details</h3><p class="cr-help">${esc(r.rejection_reason||'—')}</p>`:''}`;$('crDetailsActions').hidden=false;const isPending=status(r)==='pending';$('crReject').hidden=!isPending;$('crApprove').hidden=!isPending;$('crDetailsCloseOnly').hidden=isPending;modal('crDetailsModal');document.body.style.overflow='hidden';}
 $('crRows').addEventListener('click',e=>{const tr=e.target.closest('[data-id]');if(tr)details(tr.dataset.id)});$('crRows').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-id]')){e.preventDefault();details(e.target.dataset.id)}});
 const reasons=['Incomplete or missing OR/CR document.','Invalid or unreadable driver’s license.','Personal information could not be verified.','Plate number or vehicle documents do not match.','Duplicate courier registration.','Does not meet courier eligibility requirements.','Other (please specify)'];$('crReasonList').innerHTML=reasons.map((r,i)=>`<label class="cr-reason-option"><input type="radio" name="crReason" value="${esc(r)}"><span>${esc(r)}</span></label>`).join('');
 $('crReject').onclick=()=>{$('crReasonDetails').value='';document.querySelectorAll('input[name="crReason"]').forEach(e=>e.checked=false);$('crReasonError').textContent='';modal('crRejectModal')};
 $('crApprove').onclick=()=>{$('crApproveMessage').textContent=`Approve the registration of ${name(selected)}?`;modal('crApproveModal')};
 function decide(action,reason=''){
  if(!selected||status(selected)!=='pending')return;
  selected.status=action;
  selected.reviewed_at=new Date().toISOString();
  selected.rejection_reason=reason;
  // The Vehicles & Drivers Approved Couriers tab reads this exact center-scoped storage key.
  persist();
  closeAll();update();
  flash(action==='approved'?`${name(selected)} is now listed under Vehicles & Drivers > Approved Couriers (UI preview).`:`${name(selected)} marked rejected in frontend preview. Backend not updated.`,false,action==='approved'?'Registration Approved':'Registration Rejected');
}
 $('crApproveConfirm').onclick=()=>decide('approved');$('crRejectConfirm').onclick=()=>{const reason=document.querySelector('input[name="crReason"]:checked')?.value;if(!reason){$('crReasonError').textContent='Please select a rejection reason.';return}const extra=$('crReasonDetails').value.trim();if(reason.startsWith('Other')&&!extra){$('crReasonError').textContent='Please specify the reason.';return}decide('rejected',reason+(extra?' — '+extra:''))};
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeAll);document.querySelectorAll('.cr-modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeAll()}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAll()});
 function archive(kind){archiveStatus=kind;$('crArchiveTitle').textContent=kind==='approved'?'Approved Couriers':'Rejected Couriers';$('crArchiveSearch').value='';drawArchive();modal('crArchiveModal')}
 function drawArchive(){const q=$('crArchiveSearch').value.toLowerCase();const rows=records.filter(r=>status(r)===archiveStatus&&[name(r),r.email,r.phone,r.plate_number].join(' ').toLowerCase().includes(q));$('crArchiveRows').innerHTML=rows.map(r=>`<tr class="cr-row" data-id="${esc(r.id)}"><td><div class="cr-person"><span class="cr-avatar">${esc(initials(r))}</span><strong>${esc(name(r))}</strong></div></td><td>${esc(val(r,'vehicle','vehicle_type'))} · ${esc(r.plate_number)}</td><td>${esc(r.email)}</td><td>${esc(r.phone)}</td><td>${esc(fdate(r.reviewed_at))}</td></tr>`).join('')||'<tr><td class="cr-empty" colspan="5">No records found.</td></tr>'}
 document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>archive(b.dataset.archive));$('crArchiveSearch').oninput=drawArchive;$('crArchiveRows').onclick=e=>{const row=e.target.closest('[data-id]');if(row){$('crArchiveModal').hidden=true;details(row.dataset.id)}};
 ['crSearch','crStatus','crDate'].forEach(id=>$(id).addEventListener('input',()=>{page=1;update()}));$('crReload').onclick=()=>{$('crSearch').value='';$('crStatus').value='pending';$('crDate').value='';page=1;update()};$('crPrev').onclick=()=>{page=Math.max(1,page-1);update()};$('crNext').onclick=()=>{page++;update()};update();
});
</script></body></html>